"""Short-lived subscriptions for public items still being generated by Desktop."""
from copy import deepcopy
import json
import select
import threading
import time
import uuid
import websocket
MAX_ITEMS = 64
MAX_TEXT = 65536
PUBLIC_FIELDS = {'agentMessage': ('text', 'phase', 'questions'), 'plan': ('text',), 'commandExecution': ('command', 'aggregatedOutput', 'exitCode', 'status'), 'reasoning': ('summary',), 'mcpToolCall': ('server', 'tool', 'status'), 'fileChange': ('changes', 'status')}
DELTAS = {'item/agentMessage/delta': ('agentMessage', 'text'), 'item/plan/delta': ('plan', 'text'), 'item/commandExecution/outputDelta': ('commandExecution', 'aggregatedOutput'), 'item/reasoning/summaryTextDelta': ('reasoning', 'summary')}

class LiveTurn:

    def __init__(self, tid):
        self.tid = tid
        self.turn = None
        self.items = {}
        self.requests = {}

    def update(self, event):
        p = event.get('params') or {}
        if p.get('threadId') != self.tid:
            return
        method = event.get('method')
        if method == 'serverRequest/resolved':
            request = self.requests.pop(p.get('requestId'), None)
            if request:
                request['resolved'].set()
            return
        if 'id' in event:
            from crb.codex.agent import public_pending_requests
            if method not in ('item/tool/requestUserInput', 'item/fileChange/requestApproval', 'item/permissions/requestApproval', 'item/commandExecution/requestApproval'):
                return
            if p.get('kind', 'command') not in ('command', 'writeStdin') or not p.get('turnId'):
                return
            if any((q.get('isSecret') for q in p.get('questions', []) if isinstance(q, dict))):
                return
            key = event['id']
            if key in self.requests or len(self.requests) >= 30:
                return
            public = public_pending_requests([event], [], self.tid)
            if public and (not public[0].get('desktopOnly')):
                public[0]['id'] = uuid.uuid4().hex
                self.requests[key] = dict(public=public[0], resolved=threading.Event(), sent=False)
            return
        if method in ('turn/started', 'turn/completed'):
            turn_id = (p.get('turn') or {}).get('id')
            if method == 'turn/started' or turn_id == self.turn:
                self.turn = turn_id if method == 'turn/started' else None
                self.items.clear()
            return
        if method not in DELTAS and method not in ('item/started', 'item/completed'):
            return
        turn_id = p.get('turnId')
        if not turn_id or (self.turn and self.turn != turn_id):
            return
        self.turn = turn_id
        item = p.get('item') or {}
        item_id = item.get('id') or p.get('itemId')
        if not item_id or (item_id not in self.items and len(self.items) >= MAX_ITEMS):
            return
        if method not in DELTAS:
            kind = item.get('type')
            if kind not in PUBLIC_FIELDS:
                return
            safe = {k: item[k] for k in PUBLIC_FIELDS[kind] if k in item}
            if len(json.dumps(safe, ensure_ascii=False)) <= MAX_TEXT:
                self.items[item_id] = dict(safe, type=kind, id=item_id)
            return
        kind, field = DELTAS[method]
        delta = p.get('delta')
        row = self.items.get(item_id)
        if not isinstance(delta, str) or not row or row['type'] != kind:
            return
        if field == 'summary':
            index = p.get('summaryIndex')
            if type(index) is not int or not 0 <= index < 16:
                return
            parts = row.setdefault(field, [])
            if not isinstance(parts, list) or not all((isinstance(s, str) for s in parts)):
                return
            if sum(map(len, parts)) + len(delta) > MAX_TEXT:
                return
            while len(parts) <= index:
                parts.append('')
            parts[index] += delta
        else:
            text = row.get(field) or ''
            if isinstance(text, str):
                row[field] = (text + delta)[:MAX_TEXT]

    def merge(self, page):
        for turn in page.get('data', []):
            if turn.get('id') != self.turn or turn.get('status') != 'inProgress':
                continue
            items = turn.setdefault('items', [])
            positions = {item.get('id'): i for i, item in enumerate(items)}
            for key, live in self.items.items():
                if key not in positions:
                    items.append(deepcopy(live))
                    continue
                saved = items[positions[key]]
                if saved.get('type') != live['type']:
                    continue
                for field in ('text', 'aggregatedOutput', 'summary', 'questions'):
                    value, old = (live.get(field), saved.get(field))
                    if isinstance(value, str) and (not old or (isinstance(old, str) and value.startswith(old))):
                        saved[field] = value
                    elif field in ('summary', 'questions') and isinstance(value, list) and (not old):
                        saved[field] = deepcopy(value)
        return page

class LiveViews:

    def __init__(self):
        self.lock = threading.RLock()
        self.subscriptions = {}
        self.retry = {}
        self.closed = False

    def watch(self, owner, tid, ttl):
        with self.lock:
            now = time.monotonic()
            if self.closed:
                return
            entry = self.subscriptions.get(tid)
            if entry:
                entry['expires'] = max(entry['expires'], now + ttl)
                return
            self.retry = {key: deadline for key, deadline in self.retry.items() if deadline > now}
            if tid in self.retry or len(self.subscriptions) >= 4:
                return
            state = LiveTurn(tid)
            sock = None
            try:
                sock = owner.open()
                result = owner.call(sock, 'thread/resume', {'threadId': tid, 'excludeTurns': True}, timeout=4, notify=state.update)
                if result['thread']['id'] != tid:
                    raise ValueError('原 App 返回的对话不匹配')
            except (ValueError, KeyError, OSError, RuntimeError, websocket.WebSocketException):
                if sock:
                    sock.shutdown()
                self.retry[tid] = now + 5
                return
            sock.settimeout(5)
            entry = dict(state=state, socket=sock, expires=time.monotonic() + ttl)
            self.subscriptions[tid] = entry
            threading.Thread(target=self._receive, args=(tid, entry), daemon=True).start()

    def _receive(self, tid, entry):
        sock = entry['socket']
        try:
            while True:
                with self.lock:
                    if self.closed or entry['expires'] <= time.monotonic():
                        break
                if not select.select([sock.sock], [], [], 0.5)[0]:
                    continue
                packet = sock.recv()
                if not packet:
                    break
                event = json.loads(packet)
                with self.lock:
                    entry['state'].update(event)
        except (OSError, ValueError, websocket.WebSocketException):
            pass
        finally:
            with self.lock:
                if self.subscriptions.get(tid) is entry:
                    del self.subscriptions[tid]
                sock.shutdown()

    def pending(self, tid):
        with self.lock:
            entry = self.subscriptions.get(tid)
            if not entry or entry['expires'] <= time.monotonic():
                return []
            return [deepcopy(r['public']) for r in entry['state'].requests.values()]

    def respond(self, tid, payload):
        from crb.codex.agent import pending_request_reply
        with self.lock:
            entry = self.subscriptions.get(tid)
            if not entry or entry['expires'] <= time.monotonic():
                raise ValueError('桌面订阅已结束，请刷新后核对')
            match = next(((key, r) for key, r in entry['state'].requests.items() if r['public']['id'] == payload.get('requestId')), None)
            if not match:
                raise ValueError('原 App 已处理该请求或连接已变化')
            key, request = match
            prompt = request['public']
            if request['sent'] or payload.get('method') != prompt['method'] or payload.get('turnId') != prompt['turnId']:
                raise ValueError('请求已变化或已提交，请刷新后核对')
            _, field, value = pending_request_reply(prompt['method'], prompt, payload)
            answer = {'decision': value} if field == 'decision' else value
            request['sent'] = True
            entry['expires'] = max(entry['expires'], time.monotonic() + 8)
            try:
                entry['socket'].send(json.dumps({'id': key, 'result': answer}, ensure_ascii=False))
            except (OSError, websocket.WebSocketException):
                return {'ok': False, 'unknown': True, 'error': '回复回执未知，请在原 App 核对'}
        if not request['resolved'].wait(6):
            return {'ok': False, 'unknown': True, 'error': '尚未收到原 App 的处理回执，请先核对'}
        return {'ok': True, 'requestId': prompt['id'], 'confirmedAt': time.time()}

    def merge(self, tid, page):
        with self.lock:
            entry = self.subscriptions.get(tid)
            if entry and entry['expires'] > time.monotonic():
                return entry['state'].merge(page)
        return page

    def close(self):
        with self.lock:
            self.closed = True
            for entry in self.subscriptions.values():
                entry['socket'].abort()
